// 质量门禁：CI 里串起 lint/typecheck/coverage/build，任一不过就红灯
function runGate(checks) {
  const results = checks.map((c) => ({ name: c.name, pass: c.run() }));
  const failed = results.filter((r) => !r.pass).map((r) => r.name);
  return failed.length === 0 ? "GREEN" : `RED: ${failed.join(",")}`;
}

const gate = runGate([
  { name: "lint", run: () => true },
  { name: "typecheck", run: () => true },
  { name: "coverage", run: () => 85 >= 80 },
  { name: "build", run: () => true },
]);
console.log(gate);

const gate2 = runGate([
  { name: "lint", run: () => false },
  { name: "typecheck", run: () => true },
  { name: "coverage", run: () => 70 >= 80 },
  { name: "build", run: () => true },
]);
console.log(gate2);
